    // Filter out invalid items from API response
    filterItem?: (item: Record<string, unknown>) => boolean;
}

/**
 * Transforms device values into their display labels
 */
const transformDeviceValue = (v: string) => {
    let label: string;

    if (v === 'mobile-ios') {
        label = 'iOS';
    } else if (v === 'mobile-android') {
        label = 'Android';
    } else if (v === 'desktop') {
        label = 'Desktop';
    } else if (v === 'bot') {
        label = 'Bot';
    } else if (v === 'unknown') {
        label = 'Unknown';
    } else {
        label = v;
    }

    return {value: v, label};
};

const FILTER_FIELD_DEFINITIONS: Record<string, FilterFieldDefinition> = {
    utm_source: {
        endpoint: 'api_top_utm_sources',
        valueKey: 'utm_source',
        transformValue: v => ({value: v || '(not set)', label: v || '(not set)'})
    },
