/**
 *
 * @param {string} text
 * @param {NodeList} buttons
 * @returns Node
 */
const findButton = (text, buttons) => {
    return Array.from(buttons).find(button => button.innerText.trim() === text);
};

/**
 * Checks if an element is selected by verifying its dataset property.
 * @param {HTMLElement} element - The element to check
 * @returns {boolean} True if the element is selected
 */
const isSelected = (element) => {
    return element.dataset.selected !== undefined;
};

/**
 * Gets the last handled GET request for posts/pages from the pretender server.
 * @param {Object} server - The Mirage server instance
 * @param {string} resourceType - Either 'posts' or 'pages'
 * @returns {Object} The last matching request
 */
const getLastResourceRequest = (server, resourceType) => {
    const requests = server.pretender.handledRequests.filter(
        r => r.url.includes(`/${resourceType}/`) && r.method === 'GET'
    );
    return requests[requests.length - 1];
};

/**
 * Gets the last handled request from the pretender server.
 * @param {Object} server - The Mirage server instance
 * @returns {Object} The last request
 */
const getLastRequest = (server) => {
    return server.pretender.handledRequests.slice(-1)[0];
};

/**
 * Verifies that a post has the expected status in the UI.
 * @param {HTMLElement} postContainer - The post container element
 * @param {string} expectedStatus - The expected status text
 */
const verifyPostStatus = (postContainer, expectedStatus) => {
    expect(postContainer.querySelector('.gh-content-entry-status').textContent)
        .to.contain(expectedStatus);
};

/**
 * Clicks a button in the context menu with the specified text.
 * @param {string} buttonText - Text of the button to click
 */
const clickContextMenuItem = async (buttonText) => {
    const contextMenu = find('.gh-posts-context-menu');
    const buttons = contextMenu.querySelectorAll('button');
    const targetButton = findButton(buttonText, buttons);
    expect(targetButton, `${buttonText.toLowerCase()} button`).to.exist;
    await click(targetButton);
};

