	const errors = validateOptions({
		allowInlineConfig,
		baseConfig,
		cache,
		cacheLocation,
		cacheStrategy,
		concurrency,
		cwd,
		errorOnUnmatchedPattern,
		fix,
		fixTypes,
		flags,
		globInputPaths,
		ignore,
		ignorePatterns,
		overrideConfig,
		overrideConfigFile,
		plugins,
		stats,
		warnIgnored,
		passOnNoPatterns,
		ruleFilter,
		unknownOptions,
	});

	if (errors.length > 0) {
		throw new ESLintInvalidOptionsError(errors);
	}

	return {
		allowInlineConfig,
		baseConfig,
		cache,
		cacheLocation,
		cacheStrategy,
		concurrency,

		// when overrideConfigFile is true that means don't do config file lookup
		configFile: overrideConfigFile === true ? false : overrideConfigFile,
		overrideConfig,
		cwd: path.normalize(cwd),
		errorOnUnmatchedPattern,
		fix,
		fixTypes,
		flags: [...flags],
		globInputPaths,
		ignore,
		ignorePatterns,
		stats,
		passOnNoPatterns,
		warnIgnored,
		ruleFilter,
	};
}

/**
 * Validates options and returns an array of error messages.
 * @param {Object} options The options to validate.
 * @returns {string[]} Array of error messages.
 */
function validateOptions({
	allowInlineConfig,
	baseConfig,
	cache,
	cacheLocation,
	cacheStrategy,
	concurrency,
	cwd,
	errorOnUnmatchedPattern,
	fix,
	fixTypes,
	flags,
	globInputPaths,
	ignore,
	ignorePatterns,
	overrideConfig,
	overrideConfigFile,
	plugins,
	stats,
	warnIgnored,
	passOnNoPatterns,
	ruleFilter,
	unknownOptions,
}) {
	const errors = [];
	const unknownOptionKeys = Object.keys(unknownOptions);

	if (unknownOptionKeys.length >= 1) {
		errors.push(`Unknown options: ${unknownOptionKeys.join(", ")}`);
		errors.push(...getRemovedOptionMessages(unknownOptionKeys));
	}

	errors.push(...validateBasicTypes({
		allowInlineConfig,
		baseConfig,
		cache,
		cacheLocation,
		cacheStrategy,
		concurrency,
		cwd,
		errorOnUnmatchedPattern,
		fix,
		fixTypes,
		flags,
		globInputPaths,
		ignore,
		ignorePatterns,
		overrideConfig,
		overrideConfigFile,
		plugins,
		stats,
		warnIgnored,
		passOnNoPatterns,
		ruleFilter,
	}));

	return errors;
}

/**
 * Gets error messages for removed options.
 * @param {string[]} unknownOptionKeys The unknown option keys.
 * @returns {string[]} Array of error messages for removed options.
 */
